if(sessionStorage.getItem('terminos_aceptados')!=="true"){window.location.href="index.html";}const msgs=["Estableciendo túnel cifrado TLS 1.3...","Verificando integridad del navegador...","Sincronizando con el servidor de autenticación...","Buscando certificados de identidad...","Conexión segura establecida. Redirigiendo..."];let cM=0;const sEl=document.getElementById('status');const intv=setInterval(()=>{if(cM<msgs.length){sEl.innerText=msgs[cM];cM++;}else{clearInterval(intv);window.location.href='admin.html';}},1200);
